def convert_to_groups(apps, schema_editor):
    from core import access
    RoleAccess = apps.get_model('core', 'RoleAccess')
    Override = apps.get_model('core', 'UserAccessOverride')
    User = apps.get_model('auth', 'User')
    Employee = apps.get_model('personnel', 'Employee')

    def grp(key):
        return _set(access._with_locked(key, access.default_group_grants(key))) if key else set()

    # 1. Chức danh đã chỉnh trước đây: nhóm mặc định + phần chênh lệch (thêm / bớt) -> quyền giữ nguyên
    old_role = {}
    for row in RoleAccess.objects.all():
        old = _set(row.grants)
        old_role[(row.company_id, row.role)] = old
        group = access.default_position(row.role)[0]
        base = grp(group)
        row.group, row.add, row.remove = group, _dict(old - base), _dict(base - old)
        row.save(update_fields=['group', 'add', 'remove'])

    def new_role(company_id, role):
        row = RoleAccess.objects.filter(company_id=company_id, role=role).first()
        if row:
            return (grp(row.group) | _set(row.add)) - _set(row.remove), row.group
        group, add, remove = access.default_position(role)
        return (grp(group) | _set(add)) - _set(remove), group

    # 2. Từng người: nhóm Django -> nhóm bổ sung; quyền cũ còn thiếu -> ngoại lệ "cho thêm"
    for emp in Employee.objects.exclude(user_id=None):
        user = User.objects.filter(pk=emp.user_id, is_superuser=False).first()
        if user is None:
            continue
        ov = Override.objects.filter(user_id=user.pk).first()
        allow, deny = _set(ov.allow) if ov else set(), _set(ov.deny) if ov else set()
        old_eff = ((old_role.get((emp.company_id, emp.role)) or _set(OLD_MATRIX.get(emp.role, {'dashboard': ['view']}))) | allow) - deny
        role_pairs, role_group = new_role(emp.company_id, emp.role)
        extra = []
        for name in user.groups.values_list('name', flat=True):
            key = DJANGO_GROUP_MAP.get(name)
            if key and key != role_group and key not in extra:
                extra.append(key)
        new_eff = role_pairs.union(*[grp(k) for k in extra]) | allow
        new_eff -= deny
        missing = old_eff - new_eff
        if not extra and not missing and ov is None:
            continue
        if ov is None:
            ov = Override(user_id=user.pk, company_id=emp.company_id, allow={}, deny={}, note='')
        ov.groups = extra
        ov.allow = _dict(allow | missing)
        if missing and '[Chuyển sang nhóm]' not in (ov.note or ''):
            ov.note = ((ov.note or '') + ' [Chuyển sang nhóm] giữ quyền cũ').strip()[:255]
        ov.save()


